# Generates ffmpeg-playground/src/misc_video.rs: vc1dsp, me_cmp, hpeldsp.
import re, sys
ex = {l.split("\t")[1].strip(): l.split("\t")[0].split("aarch64_")[1] + ".S" for l in open(sys.argv[1])}
out = ['''//! libavcodec/aarch64 vc1dsp_neon.S, me_cmp_neon.S, hpeldsp_neon.S.
//! Generated by gen/misc_video.py.
//!
//! VC-1 inverse transforms work on an 8x8 int16 array (the WxH variants use
//! its first rows/columns); the loop filters touch 4 samples each side of a
//! 4/8/16-sample edge (h: a vertical edge). me_cmp compares a w-wide block of
//! h rows (h in 4..16, a multiple of 4; x2 reads one more column, y2 one more
//! row); the context argument is never read. hpeldsp likewise.
use bums_macros as bums;
''']
def emit(name, args, pre, sig):
    if name not in ex:
        print("missing", name, file=sys.stderr); return
    out.append(f'''#[bums::check_mem_safe("{ex[name]}", {", ".join(args)},
    [{", ".join(pre)}])]
fn {name}({sig});
''')
emit("ff_vc1_inv_trans_8x8_neon", ["block.as_mut_ptr()"], ["block.len() == 64"], "block: &mut [i16]")
for w, h in ((8, 4), (4, 8), (4, 4), (8, 8)):
    for dc in ("", "_dc"):
        if (w, h) == (8, 8) and not dc: continue
        emit(f"ff_vc1_inv_trans_{w}x{h}{dc}_neon", ["dest.as_mut_ptr()", "stride", "block.as_mut_ptr()"],
             [f"dest.len() == {h - 1} * stride + {w}", f"stride >= {w}", "stride <= 1073741824", "block.len() == 64"],
             "dest: &mut [u8], stride: usize, block: &mut [i16]")
for n in (4, 8, 16):
    emit(f"ff_vc1_v_loop_filter{n}_neon", ["src.as_mut_ptr().add(4 * stride)", "stride", "pq"],
         [f"src.len() == 7 * stride + {n}", f"stride >= {n}", "stride <= 1073741824", "pq <= 31"], "src: &mut [u8], stride: usize, pq: usize")
    emit(f"ff_vc1_h_loop_filter{n}_neon", ["src.as_mut_ptr().add(4)", "stride", "pq"],
         [f"src.len() == {n - 1} * stride + 8", "stride >= 8", "stride <= 1073741824", "pq <= 31"], "src: &mut [u8], stride: usize, pq: usize")
emit("ff_vc1_unescape_buffer_helper_neon", ["src.as_ptr()", "size", "dst.as_mut_ptr()"],
     ["src.len() == size", "dst.len() == size", "size >= 4", "size <= 1073741824"], "src: &[u8], size: usize, dst: &mut [u8]")
for name in sorted(ex):
    if ex[name] != "me_cmp_neon.S": continue
    m = re.match(r"(?:ff_)?(pix_abs|sse|vsad|vsse|nsse|pix_median_abs|vsad_intra|vsse_intra)(\d+)(_x2|_y2|_xy2)?_neon(_dotprod)?$", name)
    if not m: print("skip", name, file=sys.stderr); continue
    kind, w, sub = m.group(1), int(m.group(2)), m.group(3) or ""
    cx = 1 if "x" in sub else 0
    ry = 1 if "y" in sub else 0
    intra = kind.endswith("_intra")
    first = "multiplier" if kind == "nsse" else "ctx.as_ptr()"
    firstsig = "multiplier: i32" if kind == "nsse" else "ctx: &[u8]"
    pre = [f"pix1.len() == (h - 1) * stride + {w}", f"stride >= {w + cx}", "stride <= 1073741824", "h % 4 == 0", "h >= 4", "h <= 16"]
    if kind != "nsse": pre.insert(0, "ctx.len() == 1")
    if intra:
        args = [first, "pix1.as_ptr()", "pix2.as_ptr()", "stride", "h"]
        pre.append("pix2.len() == 1")
    else:
        args = [first, "pix1.as_ptr()", "pix2.as_ptr()", "stride", "h"]
        pre.append(f"pix2.len() == (h - 1 + {ry}) * stride + {w + cx}")
    emit(name, args, pre, f"{firstsig}, pix1: &[u8], pix2: &[u8], stride: usize, h: usize")
for name in sorted(ex):
    if ex[name] != "hpeldsp_neon.S" or "h264" in name: continue
    m = re.match(r"ff_(put|avg)_pixels(\d+)(_x2|_y2|_xy2)?(_no_rnd)?_neon$", name)
    if not m: print("skip", name, file=sys.stderr); continue
    w, sub = int(m.group(2)), m.group(3) or ""
    cx = 1 if "x" in sub else 0
    ry = 1 if "y" in sub else 0
    emit(name, ["block.as_mut_ptr()", "pixels.as_ptr()", "line_size", "h"],
         [f"block.len() == (h - 1) * line_size + {w}", f"pixels.len() == (h - 1 + {ry}) * line_size + {w + cx}",
          f"line_size >= {w + cx}", "line_size <= 1073741824", "h % 4 == 0", "h >= 4", "h <= 16"],
         "block: &mut [u8], pixels: &[u8], line_size: usize, h: usize")
for op in ("put", "avg"):
    for n in (16, 8):
        emit(f"ff_{op}_h264_qpel{n}_mc00_neon", ["dst.as_mut_ptr()", "src.as_ptr()", "stride"],
             [f"dst.len() == {n - 1} * stride + {n}", f"src.len() == {n - 1} * stride + {n}", f"stride >= {n}", "stride <= 1073741824"],
             "dst: &mut [u8], src: &[u8], stride: usize")
print("\n".join(out))
